CREATE OR REPLACE FUNCTION public.planning_terrain_references()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF NOT public.planning_terrain_lire_autorise() THEN RAISE EXCEPTION 'Accès refusé' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('personnes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'nom',e.nom,'prenom',e.prenom,'origine','employe','actif',e.actif,'poste',e.poste_principal,'statut',e.statut_contrat,'telephone',coalesce(e.mobile,e.telephone),'chef',e.est_chef_equipe_terrain,'permis',coalesce(to_jsonb(di.permis),to_jsonb(e.categories_permis)),'caces',to_jsonb(di.caces),'caces_autre',di.caces_autre,'dispos_id',di.id)) FROM employes e LEFT JOIN LATERAL (SELECT d.id,d.permis,d.caces,d.caces_autre FROM dispos_intervenants d WHERE d.employe_id=e.id ORDER BY d.actif DESC, d.cree_le LIMIT 1) di ON true),'[]'::jsonb) || coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nom',nom,'prenom',prenom,'origine','dispos','actif',actif,'poste',poste_terrain,'statut',statut_terrain,'telephone',telephone,'chef',est_chef_equipe_terrain,'permis',to_jsonb(permis),'caces',to_jsonb(caces),'caces_autre',caces_autre,'dispos_id',id)) FROM dispos_intervenants WHERE employe_id IS NULL),'[]'::jsonb),'affaires',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'numero',numero,'nom',nom)) FROM affaires),'[]'::jsonb)); END $function$;

CREATE OR REPLACE FUNCTION public.planning_terrain_semaine(_debut date, _fin date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF NOT planning_terrain_lire_autorise() OR _fin<_debut OR _fin-_debut>31 THEN RAISE EXCEPTION 'Accès ou période invalide'; END IF; RETURN jsonb_build_object('references',planning_terrain_references(),'affectations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'employe_id',employe_id,'dispos_intervenant_id',dispos_intervenant_id,'etape_id',etape_logistique_id,'date',date,'affaire_id',affaire_id,'role',role_terrain,'validation',validation_logistique,'confirmation',statut_confirmation,'historique',historique_terrain)) FROM assignations WHERE date BETWEEN _debut AND _fin),'[]'::jsonb),'etapes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'date',e.date_debut,'fin',coalesce(e.date_fin,e.date_debut),'heure',e.heure_debut,'heure_fin',e.heure_fin,'horaire_libre',e.horaire_libre,'note',e.note,'nb_vehicules',e.nb_vehicules,'nb_chefs_equipe',e.nb_chefs_equipe,'type',e.type,'nb_personnes',e.nb_personnes,'responsable',e.responsable,'lieu',coalesce(e.lieu_libre,a.lieu),'numero',a.numero,'nom',a.nom,'affaire_id',a.id)) FROM affaire_etapes_logistiques e JOIN affaires a ON a.id=e.affaire_id WHERE e.date_debut<=_fin AND coalesce(e.date_fin,e.date_debut)>=_debut AND e.statut<>'annule'),'[]'::jsonb),'dispos',coalesce((SELECT jsonb_agg(jsonb_build_object('intervenant_id',d.intervenant_id,'employe_id',i.employe_id,'jour',d.jour,'journee',d.journee,'soiree',d.soiree,'pas_dispo',d.pas_dispo)) FROM dispos_jours d JOIN dispos_intervenants i ON i.id=d.intervenant_id WHERE d.jour BETWEEN _debut AND _fin),'[]'::jsonb)); END $function$;